    """Build results JSONB structure from analysis outputs.

    This function is generic and does not re-run analysis; it simply
    aggregates files and, if present, ingests the analysis_results JSON.
    """
    results_folder = Path("../results")
    analysis_output = load_analysis_results(elab_id)

    # Determine status
    if analysis_output and isinstance(analysis_output, dict):
        status = analysis_output.get("status", "pending")
        analysis_metadata = analysis_output.get("metadata", {})
        warnings_list = analysis_output.get("warnings", [])
        data_outputs = analysis_output.get("data_outputs", {})
        plots = analysis_output.get("plots", {})
    else:
        status = "pending"
        analysis_metadata = {}
        warnings_list = []
        data_outputs = {}
        plots = {}

    elab_str = str(elab_id)

    # Data files discovered by convention
    per_well = results_folder / f"per_well_results_{elab_str}.csv"
    if per_well.exists():
        data_outputs.setdefault("per_well_results_csv", str(per_well.resolve()))
    agg = results_folder / f"aggregated_results_{elab_str}.csv"
    if agg.exists():
        data_outputs.setdefault("aggregated_results_csv", str(agg.resolve()))
    fits = results_folder / f"langmuir_fits_{elab_str}.csv"
    if fits.exists():
        data_outputs.setdefault("langmuir_fits_csv", str(fits.resolve()))
    tecan_xlsx = results_folder / f"tecan_data_{elab_str}.xlsx"
    if tecan_xlsx.exists():
        data_outputs.setdefault("tecan_raw_data_xlsx", str(tecan_xlsx.resolve()))

    analysis_json_path = results_folder / f"analysis_results_{elab_str}.json"
    if analysis_json_path.exists():
        data_outputs.setdefault("analysis_results_json", str(analysis_json_path.resolve()))

    # Plots
    plot_png = results_folder / f"loading_isotherms_{elab_str}.png"
    if plot_png.exists():
        plots.setdefault("loading_isotherms_png", str(plot_png.resolve()))

    results = {
        "analysis_status": status,
        "analysis_timestamp": datetime.now(timezone.utc).isoformat(),
        "summary": {
            "num_ligand_concentrations": analysis_metadata.get("num_ligand_concentrations"),
            "num_salt_concentrations": analysis_metadata.get("num_salt_concentrations"),
            "replicates": analysis_metadata.get("replicates"),
            "num_warnings": len(warnings_list),
        },
        "analysis_metadata": analysis_metadata,
        "warnings": warnings_list,
        "data_files": data_outputs,
        "plots": plots,
        "raw_analysis_output": analysis_output or {},
    }

    return results


# ============================================================================
# MAIN FUNCTIONS
# ============================================================================


def upsert_process_schema(cursor):
    """Insert or update process schema."""
    cursor.execute(
        """
        INSERT INTO process_schemas (
            process_id, process_name, version,
            metadata_schema, results_schema, field_mapping, expected_files
        ) VALUES (%s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (process_id) DO UPDATE SET
            process_name = EXCLUDED.process_name,
            metadata_schema = EXCLUDED.metadata_schema,
            results_schema = EXCLUDED.results_schema,
            field_mapping = EXCLUDED.field_mapping,
            expected_files = EXCLUDED.expected_files,
            updated_at = NOW()
        """,
        (
            PROCESS_ID,
            PROCESS_NAME,
            PROCESS_VERSION,
            json.dumps(METADATA_SCHEMA),
            json.dumps(RESULTS_SCHEMA),
            json.dumps(FIELD_MAPPING),
            json.dumps(EXPECTED_FILES),
        ),
    )


def upsert_experiment(cursor, elab_id, data):
    """Insert or update experiment execution."""
    cursor.execute(
        """
        INSERT INTO experiment_executions (
            elab_id, elab_title, process_id, process_name, lab_id,
            status, "user", workflow_json, metadata, raw_data, results
        ) VALUES (%s, %s, %s, %s, %s, %s, %s, %s, %s, %s, %s)
        ON CONFLICT (elab_id) DO UPDATE SET
            elab_title = EXCLUDED.elab_title,
            status = EXCLUDED.status,
            metadata = EXCLUDED.metadata,
            raw_data = EXCLUDED.raw_data,
            results = EXCLUDED.results,
            workflow_json = EXCLUDED.workflow_json,
            updated_at = NOW()
        RETURNING id
        """,
        (
            elab_id,
            data["title"],
            PROCESS_ID,
            PROCESS_NAME,
            data["lab_id"],
            data["status"],
            data["user"],
            json.dumps(data["workflow_json"]) if data["workflow_json"] is not None else None,
            json.dumps(data["metadata"]),
            json.dumps(data["raw_data"]),
            json.dumps(data["results"]),
        ),
    )
    row = cursor.fetchone()
    return row[0] if row else None


def main():
    parser = argparse.ArgumentParser(description=f"Commit {PROCESS_NAME} to database")
    parser.add_argument("elab_id", type=int, help="eLabFTW experiment ID")
    parser.add_argument(
        "--dry-run",
        action="store_true",
        help="Don't commit, just show what would be done",
    )
    parser.add_argument(
        "--init-schema-only",
        action="store_true",
        help="Only initialize process schema",
    )
    args = parser.parse_args()

    conn = None
    try:
        conn = get_db_connection()
        cursor = conn.cursor()

        # Always upsert schema
        upsert_process_schema(cursor)
        print(f"Process schema updated: {PROCESS_NAME} (ID: {PROCESS_ID})")

        if args.init_schema_only:
            conn.commit()
            print("Schema-only mode, skipping experiment data.")
            return 0

        # Load experiment data
        exp_json_path = find_experiment_json(args.elab_id)
        with open(exp_json_path) as f:
            exp_data = json.load(f)

        # Extract fields
        extra_fields = exp_data.get("metadata_decoded", {}).get("extra_fields", {})
        workflow_json, lab_id = load_workflow()

        metadata = extract_metadata(extra_fields)
        raw_data = build_raw_data(args.elab_id)
        results = build_results(args.elab_id)

        status = "completed" if results.get("analysis_status") == "success" else "pending"

        data = {
            "title": exp_data.get("title", ""),
            "lab_id": lab_id,
            "status": status,
            "user": exp_data.get("userid_human", ""),
            "workflow_json": workflow_json,
            "metadata": metadata,
            "raw_data": raw_data,
            "results": results,
        }

        if args.dry_run:
            print("DRY RUN - Would insert:")
            print(json.dumps(data, indent=2, default=str))
            conn.rollback()
            return 0

        exp_db_id = upsert_experiment(cursor, args.elab_id, data)
        conn.commit()

        print(f"Experiment {args.elab_id} committed successfully (DB ID: {exp_db_id})")
        return 0

    except Exception as e:
        print(f"Error: {e}", file=sys.stderr)
        if conn is not None:
            try:
                conn.rollback()
            except Exception:
                pass
        return 1
    finally:
        if conn is not None:
            try:
                conn.close()
            except Exception:
                pass


if __name__ == "__main__":
    sys.exit(main())

